def find_conflicts(sessions: Sequence[Session]) -> List[Tuple[Session, Session]]:
    """Return each conflicting pair exactly once, ordered by their positions.

    Sessions clash when they occur on the same day, their time intervals truly overlap
    (touching endpoints does not count), and they share a room or at least one student group.
    """
    conflicts: List[Tuple[Session, Session]] = []
    for i, a in enumerate(sessions):
        for j in range(i + 1, len(sessions)):
            b = sessions[j]
            if a.day != b.day:
                continue
            if a.overlaps(b) and _shares_resource(a, b):
                conflicts.append((a, b))
